    { name: 'Kevin', avatar: '🧑', active: true },
    { name: 'Alice', avatar: '👩', active: false },
    { name: 'Zayn', avatar: '🧔', active: false },
    { name: 'Miya', avatar: '👩‍🦰', active: true },
