    { name: 'Royan', location: 'Bandung, Indonesia', followed: false },
    { name: 'Wati', location: 'Bekasi, Indonesia', followed: true },
    { name: 'Jacks', location: 'Banten, Tangiers', followed: true },
    { name: 'Jason', location: 'Rache, Singapore', followed: false },
