  const activities = [
    { user: 'Tiara.sehent', action: 'and 16 others start following you', time: '5 Min', avatar: '👩' },
    { user: 'Ui_Manola', action: 'Commented on your post : Amazing', time: '8 Min', avatar: '👨' },
    { user: 'Mayz', action: 'Start following you', time: '2 Min', avatar: '👤' },
