  const yesterdayActivities = [
    { user: 'Hanna.ui', action: 'and 402 others liked your posts', time: '1 Day', avatar: '👩' },
    { user: 'Mawang21', action: 'Commented on your post : Very Useful!!', time: '1 Day', avatar: '👨' },
  ];

